import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-12-12 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-12-12 :: Ceph Performance Meeting","date":"2019-12-12T00:00:00.000Z","updated":"2019-12-13T00:00:00.000Z","tags":["Ceph","Performance Optimization","BlueStore","Distributed Storage","Storage Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-12_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-12-12_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),l={name:"posts/2019/2019-12-12_-_-_Ceph_Performance_Meeting.md"};function i(n,e,s,g,h,_){return r(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><strong>文档更新</strong>：来自heat的PR更新了关于CPU和内存推荐的文档，调整了之前建议的1GB内存每TB硬盘空间的配置，使其更符合BlueStore的实际情况。</li><li><strong>已关闭的PR</strong>： <ul><li><strong>I/O Ewing支持</strong>：已合并。</li><li><strong>BlueStore数据库空间智能使用框架</strong>：Igor的工作，改进了数据库空间的使用效率。</li></ul></li><li><strong>其他更新</strong>： <ul><li><strong>VL APR</strong>：因测试中遇到bug，暂时关闭，计划未来重新提交。</li><li><strong>OP Tracker PR</strong>：因争议性较大，被Dale bot关闭，建议重新设计接口。</li><li><strong>Op Tracker默认禁用</strong>：决定不实施。</li><li><strong>Finisher优化</strong>：更新后需要重新测试。</li><li><strong>CLS桶列表过滤优化</strong>：减少了数据传输量，已进入测试阶段。</li></ul></li></ol><h4 id="性能优化讨论" tabindex="-1">性能优化讨论 <a class="header-anchor" href="#性能优化讨论" aria-label="Permalink to &quot;性能优化讨论&quot;">​</a></h4><ul><li><strong>PG Log优化</strong>：通过移除PG Log的OMAP写入和完全禁用PG Log，观察到性能和尾部延迟的显著改善。</li><li><strong>内存目标调整</strong>：增加内存目标以减少映射条目读取，提高吞吐量。</li><li><strong>BlueStore优化</strong>：讨论了BlueStore中PG Log和OMAP的优化策略，包括简化数据结构和直接写入对象数据的可能性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续运行测试，包括在新的节点上进行测试，以及在RGW案例中验证优化效果。</li><li>调查并解决最近一个月内可能影响性能的合并问题。</li><li>进一步分析和优化PG Log代码，包括可能的微基准测试。</li><li>探索使用Crimson作为潜在的优化方案。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议决定下周继续讨论，之后将有一段时间的休息。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了持续优化Ceph存储系统的必要性，特别是在性能和资源管理方面。团队将继续进行深入测试和分析，以实现更高效的存储解决方案。</p><p>会议详细讨论了Ceph存储系统的性能优化，包括文档更新、已关闭的PR、其他更新、性能优化讨论以及后续行动计划。重点优化了PG Log、内存目标和BlueStore，并计划进行更多测试和分析。</p>',12)])])}const c=t(l,[["render",i]]);export{d as __pageData,c as default};
